(function() {
  'use strict';

  function throttle(func, limit) {
    let inThrottle;
    return function(...args) {
      if (!inThrottle) {
        func.apply(this, args);
        inThrottle = true;
        setTimeout(() => inThrottle = false, limit);
      }
    };
  }

  const handlePointerMove = function(e) {
    document.querySelectorAll('.card').forEach(function(card) {
      const rect = card.getBoundingClientRect();
      const rotateX = ((e.clientY - rect.top) / rect.height - 0.5) * -6;
      const rotateY = ((e.clientX - rect.left) / rect.width - 0.5) * 6;
      card.style.setProperty('--tilt-x', rotateX.toFixed(2) + 'deg');
      card.style.setProperty('--tilt-y', rotateY.toFixed(2) + 'deg');
    });
  };

  const throttledHandler = throttle(handlePointerMove, 16);

  if (typeof CardSpoke_MODS !== 'undefined') {
    CardSpoke_MODS.register('quantum-kaleidoscope-theme-js', {
      onEnable(ctx) {
        ctx.logger.log('Enabling Quantum Kaleidoscope motion effects.');
        document.addEventListener('pointermove', throttledHandler);
      },
      onDisable(ctx) {
        ctx.logger.log('Disabling Quantum Kaleidoscope motion effects.');
        document.removeEventListener('pointermove', throttledHandler);
        document.querySelectorAll('.card').forEach(function(card) {
          card.style.removeProperty('--tilt-x');
          card.style.removeProperty('--tilt-y');
        });
      }
    });
  } else {
    document.addEventListener('pointermove', throttledHandler);
  }
})();

